import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { writeFile } from 'node:fs/promises';
const require=createRequire(import.meta.url);
const rows=[];
for(const [build,api] of [
  ['source',await import('/Users/aantich/dev/oneringai/src/index.ts')],
  ['esm',await import('@everworker/oneringai')],
  ['cjs',require('@everworker/oneringai')],
] as const) {
  const {AgentContextNextGen,BasePluginNextGen,PluginRegistry}=api;
  let seen:unknown;
  class Existing extends BasePluginNextGen {
    readonly name='legacy_task_view';
    getInstructions(){return 'Existing external task plugin';}
    async getContent(){return 'LEGACY_TASK_PLUGIN_MARKER';}
    getContents(){return seen;}
  }
  PluginRegistry.register('legacy_task_view',(config:unknown)=>{seen=config;return new Existing();},{featureKey:'taskState'});
  let context;
  try {
    // Plain JavaScript/tsx demonstrates that this existing extension still runs;
    // the separately compiled public consumer shows the introduced type break.
    context=AgentContextNextGen.create({model:'gpt-4o-mini',features:{workingMemory:false,inContextMemory:false,taskState:true},plugins:{taskState:{existingCustomOption:true}}} as any);
    const prepared=await context.prepare();
    assert.deepEqual(seen,{existingCustomOption:true});
    assert.ok(JSON.stringify(prepared.input).includes('LEGACY_TASK_PLUGIN_MARKER'));
    assert.equal(context.getPlugin('task_state'),null);
    rows.push({build,customRegistryStillWorksAtRuntime:true,config:seen,providerCalls:0});
  } finally {context?.destroy();PluginRegistry.remove('taskState');}
}
await writeFile('/tmp/oneringai-stage04-review2-runtime.json',JSON.stringify(rows,null,2)+'\n');
console.log(JSON.stringify(rows,null,2));
